using System;
using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace Azure.ResourceManager
{
    internal sealed class ResponseErrorConverter : JsonConverter<ResponseError>
    {
        public override ResponseError Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            using JsonDocument doc = JsonDocument.ParseValue(ref reader);
            return ReadResponseError(doc.RootElement);
        }

        public override void Write(Utf8JsonWriter writer, ResponseError value, JsonSerializerOptions options)
        {
            writer.WriteStartObject();
            if (value.Code != null)
            {
                writer.WriteString("code"u8, value.Code);
            }
            if (value.Message != null)
            {
                writer.WriteString("message"u8, value.Message);
            }
            if (value.Target != null)
            {
                writer.WriteString("target"u8, value.Target);
            }
            if (value.Details != null && value.Details.Count > 0)
            {
                writer.WriteStartArray("details"u8);
                foreach (var detail in value.Details)
                {
                    Write(writer, detail, options);
                }
                writer.WriteEndArray();
            }
            if (value.InnerError != null)
            {
                writer.WritePropertyName("innererror"u8);
                WriteInnerError(writer, value.InnerError);
            }
            writer.WriteEndObject();
        }

        private static void WriteInnerError(Utf8JsonWriter writer, ResponseInnerError innerError)
        {
            writer.WriteStartObject();
            if (innerError.Code != null)
            {
                writer.WriteString("code"u8, innerError.Code);
            }
            if (innerError.InnerError != null)
            {
                writer.WritePropertyName("innererror"u8);
                WriteInnerError(writer, innerError.InnerError);
            }
            writer.WriteEndObject();
        }

        private static ResponseError ReadResponseError(JsonElement element)
        {
            string code = null;
            string message = null;
            string target = null;
            List<ResponseError> details = null;
            ResponseInnerError innerError = null;

            foreach (var property in element.EnumerateObject())
            {
                if (property.NameEquals("code"u8))
                {
                    code = property.Value.GetString();
                }
                else if (property.NameEquals("message"u8))
                {
                    message = property.Value.GetString();
                }
                else if (property.NameEquals("target"u8))
                {
                    target = property.Value.GetString();
                }
                else if (property.NameEquals("details"u8))
                {
                    if (property.Value.ValueKind == JsonValueKind.Array)
                    {
                        details = new List<ResponseError>();
                        foreach (var item in property.Value.EnumerateArray())
                        {
                            details.Add(ReadResponseError(item));
                        }
                    }
                }
                else if (property.NameEquals("innererror"u8))
                {
                    innerError = ReadInnerError(property.Value);
                }
            }

            return new ResponseError(code, message, target, default, innerError, details);
        }

        private static ResponseInnerError ReadInnerError(JsonElement element)
        {
            if (element.ValueKind == JsonValueKind.Null)
            {
                return null;
            }

            string code = null;
            ResponseInnerError inner = null;

            foreach (var property in element.EnumerateObject())
            {
                if (property.NameEquals("code"u8))
                {
                    code = property.Value.GetString();
                }
                else if (property.NameEquals("innererror"u8))
                {
                    inner = ReadInnerError(property.Value);
                }
            }

            return new ResponseInnerError(code, inner);
        }
    }
}

